const defaults={jobs:seedJobs,saved:[],applications:[],profile:{name:'',headline:'',email:'',mobile:'',city:'Lahore',summary:'',skills:'',experience:'',education:'',desired:'',salary:'',visibility:'Employers only'},documents:[],portfolio:[],cvs:[],company:{name:'',industry:'IT & Software',size:'11–50',about:'',city:'Lahore',status:'Draft'},notes:{},unlocked:[],credits:0,downloadCredits:0,team:[],activity:[],alerts:[],plans:[{name:'Free',price:'0',days:15,validity:0,posts:2,views:0,downloads:0,featured:0,team:1},{name:'Basic',price:'',days:30,validity:30,posts:3,views:20,downloads:10,featured:0,team:2},{name:'Standard',price:'',days:30,validity:90,posts:10,views:100,downloads:50,featured:2,team:5},{name:'Premium',price:'',days:45,validity:365,posts:30,views:500,downloads:250,featured:10,team:15}],masters:{cities:'Lahore,Karachi,Islamabad,Rawalpindi,Multan,Faisalabad,Peshawar',categories:'IT & Software,Design & Creative,HR & Recruitment,Sales & Marketing,Finance & Accounting,Customer Support',skills:'React,Figma,Excel,SEO,Recruitment,Communication',industries:'IT & Software,Finance,Retail,Healthcare,Education'},sources:[]};
let db=JSON.parse(localStorage.getItem('hrwala-v1')||'null')||structuredClone(defaults);for(const k in defaults)if(db[k]===undefined)db[k]=structuredClone(defaults[k]);let role='seeker',page='home',sub='Overview',query='',city='',category='',type='',mode='',minSalary='',experience='',dateFilter='',wizard=0,cvTemplate='Classic';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),money=n=>Number(n).toLocaleString('en-PK'),persist=()=>localStorage.setItem('hrwala-v1',JSON.stringify(db));
function log(action){db.activity.unshift({action,time:new Date().toISOString(),actor:role});persist()}function toast(t){$('#toast').innerHTML='<div class="toast">'+esc(t)+'</div>';setTimeout(()=>$('#toast').innerHTML='',3600)}function go(p,s){page=p;if(s)sub=s;render();window.scrollTo(0,0)}function dash(r){role=r;go('dashboard','Overview')}function options(arr,val){return arr.map(x=>'<option '+(x===val?'selected':'')+'>'+esc(x)+'</option>').join('')}function list(k){return db.masters[k].split(',').map(x=>x.trim()).filter(Boolean)}
function field(label,name,value='',kind='text',choices=null,required=false){return '<label class="field '+(kind==='textarea'?'full':'')+'">'+label+(required?' *':'')+(choices?'<select name="'+name+'">'+options(choices,value)+'</select>':kind==='textarea'?'<textarea name="'+name+'" '+(required?'required':'')+'>'+esc(value)+'</textarea>':'<input name="'+name+'" type="'+kind+'" value="'+esc(value)+'" '+(required?'required':'')+'>')+'</label>'}
function header(){return '<header><a class="brand" href="./"><span class="logo">hr</span><b>HR</b>Wala<small>.net</small></a><nav><a href="./">Discover</a>'+[['home','Job Portal'],['jobs','Find a job'],['companies','Companies'],['resources','Career resources']].map(([p,n])=>'<a href="#'+p+'" onclick="go(\''+p+'\');return false" class="'+(page===p?'active':'')+'">'+n+'</a>').join('')+'</nav><div class="topactions"><button class="btn ghost" onclick="dash(\'employer\')">For employers ↗</button><button class="btn sm light" onclick="go(\'signin\')">Sign in</button><button class="btn sm" onclick="dash(\'seeker\')">My dashboard</button></div></header><div class="demo">INTERACTIVE PREVIEW · Illustrative jobs & candidates · Data saved on this browser · Job seekers are always free</div>'}
function footer(){return '<footer><div class="brand"><span class="logo">hr</span><b>HR</b>Wala<small>.net</small></div><span>Connecting people. Creating possibilities.</span><div><a href="#" onclick="policy(\'Terms of use\');return false">Terms</a> &nbsp; · &nbsp; <a href="#" onclick="policy(\'Privacy policy\');return false">Privacy</a> &nbsp; · &nbsp; <a href="#" onclick="policy(\'Posting policy\');return false">Posting policy</a> &nbsp; · &nbsp; <a href="#" onclick="dash(\'admin\');return false">Admin preview</a></div><span>© '+new Date().getFullYear()+' HRWala.net</span></footer>'}
function jobCard(j){return '<article class="job">'+(j.featured?'<span class="featured">FEATURED</span>':'')+'<div class="companyline"><div class="companylogo">'+esc(j.logo||j.company.slice(0,2))+'</div><div><b>'+esc(j.company)+'</b><small>'+esc(j.category)+'</small></div><button aria-label="Save '+esc(j.title)+'" class="bookmark '+(db.saved.includes(j.id)?'saved':'')+'" onclick="saveJob('+j.id+')">'+(db.saved.includes(j.id)?'♥':'♡')+'</button></div><h3><a href="#job" onclick="jobDetail('+j.id+');return false">'+esc(j.title)+'</a></h3><div class="meta"><span>⌖ '+esc(j.city)+'</span><span>◷ '+esc(j.exp)+'+ years</span></div><div class="tags"><span class="tag blue">'+esc(j.type)+'</span><span class="tag">'+esc(j.mode)+'</span><span class="tag green">'+(j.status||'Open')+'</span></div><div class="jobfoot"><span class="salary">PKR '+money(j.salary)+'–'+money(j.max)+'<small> / mo</small></span><button class="btn ghost sm" onclick="jobDetail('+j.id+')">View job ↗</button></div></article>'}
function home(){return '<section class="hero"><div><div class="eyebrow">Your next chapter starts here</div><h1>Find your people.<br>Find your <em>potential.</em></h1><p>Meaningful opportunities. Ambitious teams.<br>A better way to connect with what comes next.</p><div class="tags"><span class="tag green">✓ Always free for job seekers</span><span class="tag">Built for careers in Pakistan</span></div></div><div class="heroart"><div class="orbit"></div><span class="dot"></span><div class="centericon">'+icons.brief+'</div><div class="floatcard f1"><i>✧</i><div><b>People first</b><small>OPPORTUNITIES THAT FIT</small></div></div><div class="floatcard f2"><i>↗</i><div><b>Your next move</b><small>STARTS WITH A CONNECTION</small></div></div><div class="floatcard f3"><i>▤</i><div><b>A CV that opens doors</b><small>BUILD YOURS, FOR FREE</small></div></div><div class="floatcard f4"><i>✓</i><div><b>Talent meets possibility</b><small>GROW TOGETHER</small></div></div></div></section><form class="searchbar" onsubmit="event.preventDefault();search(this)"><label>⌕ <input aria-label="Job keyword" name="q" placeholder="Job title, keyword or company"></label><label>⌖ <select aria-label="Job location" name="city"><option value="">All locations</option>'+options(list('cities'),'')+'</select></label><button class="btn">Find opportunities ↗</button></form><div class="popular">Popular searches: '+['UI/UX Designer','Frontend Developer','Marketing','Human Resources'].map(x=>'<button onclick="query=\''+x+'\';go(\'jobs\')">'+x+'</button>').join('')+'</div><main class="container"><div class="sectionhead"><div><h2>A world of possibilities</h2><p>Explore opportunities in your area of expertise.</p></div><a class="btn ghost sm" href="#jobs" onclick="category=\'\';go(\'jobs\');return false">All categories ↗</a></div><div class="cats">'+list('categories').map((c,i)=>'<button class="cat" onclick="category=\''+esc(c)+'\';go(\'jobs\')"><span class="iconbox">'+['⌘','✧','♧','↗','▥','☏'][i%6]+'</span><b>'+esc(c)+'</b><small>Explore opportunities ↗</small></button>').join('')+'</div><div class="sectionhead"><div><div class="eyebrow">Take the next step</div><h2>Opportunities worth exploring</h2><p>A selection of roles to inspire your next move.</p></div><button class="btn ghost sm" onclick="query=\'\';category=\'\';go(\'jobs\')">View all jobs ↗</button></div><div class="jobs">'+db.jobs.filter(j=>!j.status||j.status==='Live').slice(0,6).map(jobCard).join('')+'</div><div class="banner"><div><h2>Great teams start with the right people.</h2><p>Post opportunities, discover talent and manage your hiring in one place.</p></div><button class="btn gold" onclick="dash(\'employer\')">Find your next hire ↗</button></div></main>'}
function search(f){let d=new FormData(f);query=d.get('q');city=d.get('city');go('jobs')}function saveJob(id){db.saved.includes(id)?db.saved=db.saved.filter(x=>x!==id):db.saved.push(id);persist();render()}
function jobsPage(saved=false){let jobs=db.jobs.filter(j=>(!j.status||j.status==='Live')&&(!saved||db.saved.includes(j.id))&&(!query||(j.title+' '+j.company+' '+j.skills).toLowerCase().includes(query.toLowerCase()))&&(!city||j.city===city)&&(!category||j.category===category)&&(!type||j.type===type)&&(!mode||j.mode===mode)&&(!minSalary||j.max>=Number(minSalary))&&(!experience||j.exp<=Number(experience)));return '<div class="container"><div class="pagehead"><div><div class="eyebrow">Your career, your direction</div><h1>'+(saved?'Saved opportunities':'Find your next opportunity')+'</h1><p>'+jobs.length+' illustrative opportunities · Applications are always free</p></div><button class="btn light sm" onclick="document.querySelector(\'.filterlayout\').classList.toggle(\'showfilters\')">☷ Filters</button></div><form class="searchbar" style="margin:0 0 25px" onsubmit="event.preventDefault();search(this)"><label>⌕<input aria-label="Search jobs" name="q" value="'+esc(query)+'" placeholder="Job title, keyword or company"></label><label>⌖<select name="city" aria-label="City"><option value="">All cities</option>'+options(list('cities'),city)+'</select></label><button class="btn">Search jobs</button></form><div class="filterlayout"><aside class="panel filters"><h3>Refine your search</h3>'+filter('Category','category',list('categories'),category)+filter('Job type','type',['Full-time','Part-time','Contract','Internship'],type)+filter('Work mode','mode',['Onsite','Hybrid','Remote'],mode)+filter('Experience up to','experience',['0','1','2','3','5','10'],experience)+'<label class="field">Minimum salary (PKR)<input type="number" min="0" value="'+esc(minSalary)+'" onchange="minSalary=this.value;render()"></label><button class="btn ghost sm" onclick="query=city=category=type=mode=experience=minSalary=\'\';render()">Clear all filters</button><hr style="border:0;border-top:1px solid var(--line)"><p style="font-size:11px">Get matching opportunities in your inbox.</p><button class="btn light sm" onclick="saveAlert()">Create a job alert</button></aside><div><div class="jobs">'+(jobs.length?jobs.map(jobCard).join(''):'<div class="panel empty">No matching opportunities. Try changing your search.</div>')+'</div></div></div></div>'}
function filter(label,k,arr,val){return '<label class="field">'+label+'<select onchange="'+k+'=this.value;render()"><option value="">Any '+label.toLowerCase()+'</option>'+options(arr,val)+'</select></label>'}function saveAlert(){db.alerts.push({query,city,category});log('Saved job alert');toast('Job alert saved. Email delivery requires a connected email service.')}
function modal(html){$('#modal').innerHTML='<div class="modalback" onclick="if(event.target===this)closeModal()"><section class="modal"><button class="modalclose" aria-label="Close dialog" onclick="closeModal()">×</button>'+html+'</section></div>'}function closeModal(){$('#modal').innerHTML=''}function jobDetail(id){let j=db.jobs.find(x=>x.id===id);modal('<div class="eyebrow">'+esc(j.company)+'</div><h2>'+esc(j.title)+'</h2><div class="meta">'+esc(j.city)+' · '+esc(j.mode)+' · '+esc(j.type)+'</div><div class="tags"><span class="tag blue">PKR '+money(j.salary)+'–'+money(j.max)+' / month</span></div><h3>About the opportunity</h3><p>'+esc(j.description||'')+'</p><h3>What you will bring</h3><p>'+esc(j.requirements||'')+'</p><div class="tags">'+(j.skills||'').split(',').map(x=>'<span class="tag">'+esc(x)+'</span>').join('')+'</div><button class="btn" onclick="applyForm('+id+')">Apply for this role ↗</button><p style="font-size:10px">No payment required. This is an illustrative job in the portal preview.</p>')}
function applyForm(id){let j=db.jobs.find(x=>x.id===id);if(j.applyMethod==='External link'&&/^https?:\/\//.test(j.applyTarget))return modal('<h2>Apply on the company website</h2><p>This job uses an external application process.</p><a class="btn" target="_blank" rel="noopener" href="'+esc(j.applyTarget)+'">Continue to employer ↗</a>');if(j.applyMethod==='Email')return modal('<h2>Apply by email</h2><p>Send your application to '+esc(j.applyTarget)+'</p>');if(db.applications.some(a=>a.jobId===id))return toast('You have already applied to this job.');if(!db.profile.name){closeModal();dash('seeker');sub='Profile';render();return toast('Complete your name and contact details before applying.')}modal('<h2>Make your next move</h2><p>Apply with your default CV. Your application stays in your history.</p><form onsubmit="event.preventDefault();submitApplication('+id+',this)">'+field('Cover note','note','','textarea')+(j.questions||'').split('\n').filter(Boolean).slice(0,5).map((q,i)=>field(q,'screening_'+i,'','text',null,true)).join('')+'<div class="notice">Default CV: '+esc(db.cvs.find(x=>x.default)?.title||'Current profile CV')+'</div><button class="btn">Submit application — free</button></form>')}
function submitApplication(id,f){db.applications.push({id:Date.now(),jobId:id,status:'Submitted',note:new FormData(f).get('note'),answers:Object.fromEntries(new FormData(f)),date:new Date().toISOString(),history:[{status:'Submitted',date:new Date().toISOString()}]});log('Application submitted');closeModal();toast('Application submitted. Track it in your dashboard.');render()}
const menus={seeker:['Overview','Profile','Documents','My CVs','Portfolio','Applications','Saved Jobs & Alerts','Notifications','Settings'],employer:['Overview','Company Profile','Post a Job','My Jobs','Applicants (ATS)','Candidate Search','Unlocked CVs','Team','Packages & Billing','Integrations','Activity Log'],admin:['Overview','Employer Approvals','Job Approvals','Users & Reports','Packages & Prices','Payments & Credits','Master Data','Content','Job Sources','Staff Roles','Audit Log']};
function workspace(){return '<div class="workspace"><aside class="sidebar"><label>'+role.toUpperCase()+' WORKSPACE</label>'+menus[role].map((m,i)=>'<button class="'+(sub===m?'active':'')+'" onclick="sub=\''+m+'\';render()"><span>'+['◫','♙','▤','▥','⌘','◎','◇','♧','⚙','⇄','◷'][i%11]+'</span>'+m+'</button>').join('')+'<label>EXPLORE THE PREVIEW</label>'+['seeker','employer','admin'].filter(r=>r!==role).map(r=>'<button onclick="dash(\''+r+'\')">'+r[0].toUpperCase()+r.slice(1)+' workspace ↗</button>').join('')+'</aside><main class="main">'+dashContent()+'</main></div>'}
function pageHead(title,desc,action=''){return '<div class="pagehead"><div><div class="eyebrow">'+role+' workspace</div><h1>'+title+'</h1><p>'+desc+'</p></div>'+action+'</div>'}function metric(label,value,detail){return '<div class="metric"><small>'+label+'</small><strong>'+value+'</strong><span>'+detail+'</span></div>'}function strength(){return Math.round(Object.values(db.profile).filter(Boolean).length/Object.keys(db.profile).length*100)}
function overview(){if(role==='seeker')return pageHead('Your next chapter, '+esc(db.profile.name.split(' ')[0]||'starts here')+'.','Your career, applications and opportunities in one place.','<button class="btn" onclick="go(\'jobs\')">Explore jobs ↗</button>')+'<div class="metrics">'+metric('Applications sent',db.applications.length,'Your complete application history')+metric('Saved opportunities',db.saved.length,'Ready when you are')+metric('Upcoming interviews',db.applications.filter(a=>a.status==='Interview').length,'Keep your next steps organised')+metric('Profile strength',strength()+'%','Help employers discover you')+'</div><div class="split"><div class="panel"><h3>Application activity</h3>'+applicationRows()+'</div><div class="panel"><div class="iconbox">✧</div><h3>A strong profile opens doors.</h3><p style="font-size:12px">Add your experience, skills and education to tell your professional story.</p><div class="progress"><i style="width:'+strength()+'%"></i></div><small>'+strength()+'% complete</small><div class="formactions"><button class="btn light sm" onclick="wizard=0;sub=\'Profile\';render()">Complete profile ↗</button></div></div></div><div class="sectionhead"><h2>Selected for your next step</h2><button class="btn ghost sm" onclick="go(\'jobs\')">View all ↗</button></div><div class="jobs">'+db.jobs.slice(0,3).map(jobCard).join('')+'</div>';
if(role==='employer')return pageHead('Build your next great team.','A clear view of your hiring, talent and package usage.','<button class="btn" onclick="sub=\'Post a Job\';render()">+ Post a job</button>')+'<div class="notice">Company status: '+esc(db.company.status)+'. Company approval is required to publish. Billing and CV credits are preview-only until secure server integrations are connected.</div><div class="metrics">'+metric('Live job posts',db.jobs.filter(j=>j.owned&&j.status==='Live').length+' / 2','Free package · 15 ad days')+metric('Applicants',db.applications.length,'Own-job applicants do not use credits')+metric('CV profile credits',db.credits,'Candidate unlocks remaining')+metric('Download credits',db.downloadCredits,'Downloads remaining')+'</div><div class="split"><div class="panel"><h3>Your hiring pipeline</h3>'+['Submitted','Shortlisted','Interview','Offered','Hired','Rejected'].map(s=>'<div class="row"><b>'+s+'</b><span class="tag blue">'+db.applications.filter(a=>a.status===s).length+'</span></div>').join('')+'</div><div class="panel"><h3>Hiring checklist</h3>'+['Complete your company profile','Submit verification documents','Choose your hiring package','Publish your first opportunity'].map((x,i)=>'<div class="row"><b>'+('0'+(i+1))+' &nbsp; '+x+'</b><span>↗</span></div>').join('')+'<div class="formactions"><button class="btn light sm" onclick="sub=\'Company Profile\';render()">Set up company ↗</button></div></div></div>';
return pageHead('Portal overview','Manage approvals, platform settings and employer access.')+'<div class="metrics">'+metric('Jobs in portal',db.jobs.length,'Illustrative + locally created')+metric('Pending jobs',db.jobs.filter(j=>j.status==='Pending').length,'Awaiting moderation')+metric('Company reviews',db.company.status==='Pending'?1:0,'Verification queue')+metric('Audit events',db.activity.length,'Preview activity history')+'</div><div class="panel"><h3>Moderation queue</h3><div class="row"><div><b>Employer approvals</b><small>Review company details and verification status.</small></div><button class="btn light sm" onclick="sub=\'Employer Approvals\';render()">Review ↗</button></div><div class="row"><div><b>Job approvals</b><small>Approve, reject or close submitted jobs.</small></div><button class="btn light sm" onclick="sub=\'Job Approvals\';render()">Review ↗</button></div></div>'+audit()}
function profileForm(){let steps=['Personal','Preferences','Experience','Education','Skills & extras','Documents'];let p=db.profile;return pageHead('Tell your professional story','Build your profile once. Use it across every application.','<button class="btn light sm" onclick="cvPreviewModal()">Preview profile ↗</button>')+'<div class="panel"><div class="tabs">'+steps.map((s,i)=>'<button class="'+(wizard===i?'active':'')+'" onclick="wizard='+i+';render()">'+(i+1)+'. '+s+'</button>').join('')+'</div><div class="steps">'+steps.map((_,i)=>'<span class="'+(i<=wizard?'on':'')+'"></span>').join('')+'</div><form onsubmit="event.preventDefault();saveProfile(this)"><div class="fields">'+(wizard===0?field('Full name','name',p.name,'text',null,true)+field('Professional headline','headline',p.headline,'text',null,true)+field('Email address','email',p.email,'email',null,true)+field('Mobile','mobile',p.mobile,'tel',null,true)+field('City','city',p.city,'text',list('cities'))+field('Province','province',p.province,'text',['Punjab','Sindh','Khyber Pakhtunkhwa','Balochistan','Islamabad Capital Territory'])+field('Country','country',p.country||'Pakistan')+field('Date of birth (optional)','dob',p.dob,'date')+field('Gender (optional)','gender',p.gender,'text',['Prefer not to say','Female','Male','Other'])+field('LinkedIn / website','website',p.website,'url')+field('Professional summary','summary',p.summary,'textarea'):wizard===1?field('Desired job titles (comma separated, up to 5)','desired',p.desired)+field('Job types','jobtypes',p.jobtypes||'Full-time')+field('Industry','industry',p.industry,'text',list('industries'))+field('Expected salary minimum (PKR)','salary',p.salary,'number')+field('Expected salary maximum (PKR)','salaryMax',p.salaryMax,'number')+field('Notice period','notice',p.notice,'text',['Immediately','15 days','30 days','60 days','90 days'])+field('Willing to relocate','relocate',p.relocate,'text',['No','Yes'])+field('Profile visibility','visibility',p.visibility,'text',['Public','Employers only','Hidden']):wizard===2?'<div class="field full"><p>Add a role with title, company, location and dates. Use one block per role.</p></div>'+field('Experience — job title, company, location, start/end dates, responsibilities','experience',p.experience,'textarea')+'<button class="btn light sm" type="button" onclick="document.querySelector(\'[name=experience]\').value+=\'\\n\\nJob title | Company | Location\\nStart: MM/YYYY | End: MM/YYYY or Present\\nResponsibilities:\'">+ Add another role</button>':wizard===3?field('Education — degree, field, institution, years and grade','education',p.education,'textarea')+'<button class="btn light sm" type="button" onclick="document.querySelector(\'[name=education]\').value+=\'\\n\\nDegree | Field of study | Institution\\nStart year – End year | Grade / CGPA\'">+ Add education</button>':wizard===4?field('Skills and proficiency (comma separated)','skills',p.skills,'text',null,true)+field('Languages and level','languages',p.languages)+field('Certifications — name, issuer, year, link','certifications',p.certifications,'textarea')+field('References (optional)','references',p.references,'textarea'):'<div class="field full"><p>Add CVs, degrees and certificates from the Documents tab. Files stay on this device in this preview.</p><button type="button" class="btn light" onclick="sub=\'Documents\';render()">Manage documents ↗</button></div>')+'</div><div class="formactions"><button class="btn ghost" type="button" onclick="wizard=Math.min(5,wizard+1);render()">Skip step</button><button class="btn">'+(wizard===5?'Save profile':'Save & continue ↗')+'</button></div></form></div>'}
function saveProfile(f){let data=Object.fromEntries(new FormData(f));if(data.desired&&data.desired.split(',').length>5)return toast('Add up to five desired job titles.');Object.assign(db.profile,data);log('Profile updated');wizard=Math.min(5,wizard+1);render();toast('Profile saved on this browser.')}
function cvPaper(snapshot){let p=snapshot||db.profile;return '<div class="cvpaper" style="'+(cvTemplate==='Modern'?'border-top:12px solid var(--blue)':cvTemplate==='Minimal'?'font-family:Georgia;':'')+'"><h2>'+esc(p.name||'Your name')+'</h2><b>'+esc(p.headline||'Professional headline')+'</b><p>'+esc([p.email,p.mobile,p.city,p.website].filter(Boolean).join(' · '))+'</p><h4>Professional summary</h4><p>'+esc(p.summary||'Your professional summary will appear here.')+'</p><h4>Experience</h4><p>'+esc(p.experience||'Add your experience to complete your CV.')+'</p><h4>Education</h4><p>'+esc(p.education||'Add your education.')+'</p><h4>Skills</h4><p>'+esc(p.skills||'Add your skills.')+'</p>'+(p.languages?'<h4>Languages</h4><p>'+esc(p.languages)+'</p>':'')+(p.certifications?'<h4>Certifications</h4><p>'+esc(p.certifications)+'</p>':'')+'</div>'}function cvPreviewModal(){modal(cvPaper())}function viewCV(i){let c=db.cvs[i];cvTemplate=c.template;modal(cvPaper(c.profile));}function printCV(){document.getElementById('printcv').innerHTML=cvPaper();window.print()}function cvs(){return pageHead('A CV that tells your story','Create multiple versions, choose a template and download as PDF.','<button class="btn" onclick="printCV()">Download PDF ↧</button>')+'<div class="split"><div><div class="panel"><h3>CV builder</h3><form onsubmit="event.preventDefault();saveCV(this)"><div class="fields">'+field('CV title','title','My professional CV','text',null,true)+field('Template','template',cvTemplate,'text',['Classic','Modern','Minimal'])+'</div><p style="font-size:11px">Profile data fills your CV automatically. PDF uses your browser’s “Save as PDF” option.</p><label style="font-size:11px"><input type="checkbox" name="default" checked> Set as default CV</label><div class="formactions"><button type="button" class="btn light sm" onclick="cvTemplate=document.querySelector(\'[name=template]\').value;render()">Update preview</button><button class="btn sm">Save CV version</button></div></form></div><div class="panel"><h3>My CV versions</h3>'+(db.cvs.map((c,i)=>'<div class="row"><div><b>'+esc(c.title)+'</b><small>'+esc(c.template)+(c.default?' · Default':'')+'</small></div><button class="btn ghost sm" onclick="viewCV('+i+')">Preview</button><button class="btn ghost sm" onclick="db.cvs.forEach(x=>x.default=false);db.cvs['+i+'].default=true;persist();render()">Set default</button></div>').join('')||'<p style="font-size:12px">Your saved versions will appear here.</p>')+'</div></div><div>'+cvPaper()+'</div></div>'}function saveCV(f){let d=Object.fromEntries(new FormData(f));if(d.default)db.cvs.forEach(c=>c.default=false);db.cvs.push({title:d.title,template:d.template,default:!!d.default,profile:structuredClone(db.profile)});cvTemplate=d.template;log('CV version saved');render();toast('CV version saved.')}
function applicationRows(){return db.applications.length?db.applications.map(a=>{let j=db.jobs.find(j=>j.id===a.jobId);return '<div class="row"><div><b>'+esc(j?.title||'Archived role')+'</b><small>'+esc(j?.company||'')+' · '+new Date(a.date).toLocaleDateString()+'</small></div><button class="tag blue" onclick="timeline('+a.id+')">'+esc(a.status)+' ↗</button></div>'}).join(''):'<div class="empty">Your next opportunity is waiting.<br><button class="btn ghost sm" onclick="go(\'jobs\')">Explore jobs ↗</button></div>'}function timeline(id){let a=db.applications.find(x=>x.id===id);modal('<h2>Application timeline</h2>'+a.history.map(x=>'<div class="row"><b>'+esc(x.status)+'</b><small>'+new Date(x.date).toLocaleString()+'</small></div>').join('')+(a.status!=='Withdrawn'?'<div class="formactions"><button class="btn light" onclick="changeStatus('+id+',\'Withdrawn\');closeModal()">Withdraw application</button></div>':''))}function changeStatus(id,s){let a=db.applications.find(a=>a.id===id);a.status=s;a.history.push({status:s,date:new Date().toISOString()});log('Application status changed to '+s);render()}
function documents(){return pageHead('Your documents','Keep CVs, certificates and supporting documents organised.')+'<div class="notice">Preview storage is device-local. Private storage, virus scanning and signed download links need the production backend. Do not upload confidential documents here.</div><div class="panel"><form onsubmit="event.preventDefault();uploadDoc(this)"><div class="fields">'+field('Document title','title','','text',null,true)+field('Visibility','visibility','Employers only','text',['Employers only','Private'])+'<label class="field full">Document (PDF, DOCX or JPG · up to 5 MB)<input name="file" type="file" accept=".pdf,.docx,.jpg,.jpeg" required></label></div><div class="formactions"><button class="btn">Add document</button></div></form></div><div class="panel">'+(db.documents.map((d,i)=>'<div class="row"><div><b>'+esc(d.title)+'</b><small>'+esc(d.name)+' · '+esc(d.visibility)+'</small></div><a class="btn light sm" href="'+d.data+'" download="'+esc(d.name)+'">Download</a></div>').join('')||'<div class="empty">No documents added yet.</div>')+'</div>'}function uploadDoc(f){let file=f.file.files[0];if(file.size>5*1024*1024)return toast('File exceeds 5 MB.');if(!/\.(pdf|docx|jpe?g)$/i.test(file.name))return toast('Choose a PDF, DOCX or JPG.');let r=new FileReader();r.onload=()=>{db.documents.push({title:f.title.value,name:file.name,visibility:f.visibility.value,data:r.result});try{persist();render();toast('Document saved to this browser.')}catch(e){db.documents.pop();toast('Browser storage full. Choose a smaller file.')}};r.readAsDataURL(file)}
function companyForm(){return pageHead('Introduce your company','Complete your profile and submit it for approval.')+'<div class="notice">Status: '+esc(db.company.status)+(db.company.reason?' · '+esc(db.company.reason):'')+'. Verification documents are admin-only in the planned production flow.</div><div class="panel"><form onsubmit="event.preventDefault();Object.assign(db.company,Object.fromEntries(new FormData(this)));db.company.status=\'Pending\';log(\'Company submitted for review\');render();toast(\'Company submitted to the preview review queue.\')"><div class="fields">'+field('Company name','name',db.company.name,'text',null,true)+field('Industry','industry',db.company.industry,'text',list('industries'))+field('Company size','size',db.company.size,'text',['1–10','11–50','51–200','201–500','500+'])+field('Website','website',db.company.website,'url')+field('City','city',db.company.city,'text',list('cities'))+field('Province','province',db.company.province)+field('Head office address','address',db.company.address,'text',null,true)+field('Public email','email',db.company.email,'email')+field('Public phone','phone',db.company.phone,'tel')+field('Social links','social',db.company.social)+field('About company','about',db.company.about,'textarea',null,true)+field('Verification document reference (preview only)','verification',db.company.verification,'text',null,true)+'</div><p style="font-size:11px">Production uploads for logo, cover and NTN/SECP documents require secure private storage.</p><div class="formactions"><button class="btn">Submit for approval ↗</button></div></form></div>'}
function postJob(){return pageHead('Make room for your next hire','Create a clear, considered opportunity for the right candidate.')+'<div class="notice">Free package: 2 live job slots · 15 ad days. '+(db.company.status!=='Approved'?'Your company needs approval before publishing. You can save a draft.':'Your company is approved. Submitted jobs enter moderation.')+'</div><div class="panel"><form onsubmit="event.preventDefault();createJob(this)"><h3>01 &nbsp; The essentials</h3><div class="fields">'+field('Job title','title','','text',null,true)+field('Category','category','','text',list('categories'))+field('Job type','type','Full-time','text',['Full-time','Part-time','Contract','Internship'])+field('Work mode','mode','Onsite','text',['Onsite','Hybrid','Remote'])+field('City','city','','text',list('cities'))+field('Number of openings','openings',1,'number',null,true)+'</div><h3 style="margin-top:30px">02 &nbsp; Role & requirements</h3><div class="fields">'+field('Description','description','','textarea',null,true)+field('Responsibilities','responsibilities','','textarea')+field('Requirements','requirements','','textarea',null,true)+field('Skills (comma separated)','skills')+field('Minimum education','education')+field('Minimum experience (years)','exp',0,'number')+field('Maximum experience (years)','expMax','','number')+field('Benefits','benefits')+'</div><h3 style="margin-top:30px">03 &nbsp; Compensation</h3><div class="fields">'+field('Salary minimum (PKR)','salary','','number')+field('Salary maximum (PKR)','max','','number')+field('Period','period','Month','text',['Month','Year'])+field('Salary visibility','salaryVisibility','Public','text',['Public','Hidden'])+'</div><h3 style="margin-top:30px">04 &nbsp; Applications & publishing</h3><div class="fields">'+field('Apply method','applyMethod','On HRWala','text',['On HRWala','External link','Email'])+field('External link or email','applyTarget')+field('Screening questions (one per line, max 5)','questions','','textarea')+field('Application deadline','deadline','','date')+field('Publish','publish','Draft','text',['Draft','Submit for approval'])+'</div><div class="formactions"><button class="btn">Save opportunity ↗</button></div></form></div>'}function createJob(f){let j=Object.fromEntries(new FormData(f));if(+j.max<+j.salary)return toast('Maximum salary must be at least the minimum.');if(j.questions.split('\n').filter(Boolean).length>5)return toast('Use up to five screening questions.');j.id=Date.now();j.company=db.company.name||'Your company';j.logo=j.company.slice(0,2);j.owned=true;j.status=j.publish==='Draft'||db.company.status!=='Approved'?'Draft':'Pending';j.salary=+j.salary;j.max=+j.max;j.exp=+j.exp;db.jobs.push(j);log('Job saved as '+j.status);sub='My Jobs';render();toast('Opportunity saved.')}
function myJobs(admin=false){let jobs=admin?db.jobs.filter(j=>j.status==='Pending'):db.jobs.filter(j=>j.owned);return pageHead(admin?'Review job submissions':'Your opportunities',admin?'Approve suitable jobs or return them for revision.':'Manage drafts, live opportunities and closed roles.','<button class="btn sm" onclick="sub=\'Post a Job\';render()">+ Post a job</button>')+'<div class="panel tablewrap"><table><thead><tr><th>Job title</th><th>Location</th><th>Status</th><th>Applicants</th><th>Actions</th></tr></thead><tbody>'+jobs.map(j=>'<tr><td><b>'+esc(j.title)+'</b><p style="margin:4px 0;font-size:10px">'+esc(j.company)+'</p></td><td>'+esc(j.city)+'</td><td><span class="tag blue">'+esc(j.status)+'</span></td><td>'+db.applications.filter(a=>a.jobId===j.id).length+'</td><td><select aria-label="Job status" onchange="setJobStatus('+j.id+',this.value)">'+options(admin?['Pending','Live','Rejected']:['Draft','Pending','Paused','Closed'],j.status)+'</select></td></tr>').join('')+'</tbody></table>'+(jobs.length?'':'<div class="empty">No opportunities in this queue yet.</div>')+'</div>'}function setJobStatus(id,s){let j=db.jobs.find(x=>x.id===id);if(s==='Pending'&&db.company.status!=='Approved')return toast('Company approval is required first.');if(s==='Live'&&db.jobs.filter(x=>x.owned&&x.status==='Live').length>=db.plans[0].posts)return toast('No live job slots available.');j.status=s;log('Job status changed to '+s);render()}
function ats(){return pageHead('Move hiring forward','Manage applicants from first introduction to their next chapter.','<button class="btn light sm" onclick="exportApplications()">Export CSV ↧</button>')+'<div class="board">'+['Submitted','Shortlisted','Interview','Offered','Hired','Rejected'].map(s=>'<section class="column"><h4>'+s+' <span class="tag">'+db.applications.filter(a=>a.status===s).length+'</span></h4>'+db.applications.filter(a=>a.status===s).map(a=>'<div class="candidate"><b>'+esc(db.profile.name||'Applicant')+'</b><p>'+esc(db.jobs.find(j=>j.id===a.jobId)?.title||'')+'</p><select aria-label="Applicant status" onchange="changeStatus('+a.id+',this.value)">'+options(['Submitted','Shortlisted','Interview','Offered','Hired','Rejected'],s)+'</select><button class="btn ghost sm" onclick="applicantNotes('+a.id+')">Notes & interview ↗</button></div>').join('')+'</section>').join('')+'</div><div class="notice">Applicants appear after submitting an application from the job seeker view. Preview actions update the same local application record.</div>'}function applicantNotes(id){let n=db.notes[id]||{};modal('<h2>Applicant details</h2><form onsubmit="event.preventDefault();db.notes['+id+']=Object.fromEntries(new FormData(this));log(\'Applicant notes updated\');closeModal();toast(\'Applicant details saved.\')"><div class="fields">'+field('Private recruiter notes','note',n.note,'textarea')+field('Rating','rating',n.rating||'3','text',['1','2','3','4','5'])+field('Interview date and time','interview',n.interview,'datetime-local')+field('Meeting location or link','location',n.location)+'</div><div class="formactions"><button class="btn">Save details</button></div></form>')}function exportApplications(){let rows=[['Candidate','Job','Status','Date'],...db.applications.map(a=>[db.profile.name,db.jobs.find(j=>j.id===a.jobId)?.title,a.status,a.date])];download('applications.csv',rows.map(r=>r.map(c=>'"'+String(c||'').replaceAll('"','""')+'"').join(',')).join('\r\n'),'text/csv')}function download(name,data,mime){let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([data],{type:mime}));a.download=name;a.click();URL.revokeObjectURL(a.href)}
const candidates=[{id:1,initials:'AK',name:'Ayesha Khan',headline:'Product Designer',city:'Lahore',exp:4,skills:'Figma · UX Research · Design Systems'},{id:2,initials:'HA',name:'Hamza Ali',headline:'Frontend Engineer',city:'Islamabad',exp:3,skills:'React · TypeScript · CSS'},{id:3,initials:'SF',name:'Sara Farooq',headline:'HR Specialist',city:'Karachi',exp:5,skills:'Recruitment · People Operations'}];function candidateSearch(unlocked=false){return pageHead(unlocked?'Your unlocked candidates':'Meet your next great hire','Illustrative profiles · '+db.credits+' profile credits remaining')+'<div class="notice">Masked profiles hide personal details until unlocked. This preview demonstrates the flow only; production credit enforcement must run on the server. Own-job applicants remain free.</div><div class="jobs">'+candidates.filter(c=>!unlocked||db.unlocked.includes(c.id)).map(c=>{let open=db.unlocked.includes(c.id);return '<div class="job"><div class="avatar">'+c.initials+'</div><h3>'+esc(open?c.name:c.initials+' · Name protected')+'</h3><b style="font-size:12px">'+c.headline+'</b><p style="font-size:11px">'+c.city+' · '+c.exp+' years experience</p><div class="tags"><span class="tag">'+c.skills+'</span></div><button class="btn light sm" onclick="unlock('+c.id+')">'+(open?'View profile ↗':'Unlock · 1 credit')+'</button></div>'}).join('')+'</div>'}function unlock(id){if(db.unlocked.includes(id))return modal('<h2>'+esc(candidates.find(c=>c.id===id).name)+'</h2><p>Illustrative candidate profile. No real contact data or CV is attached.</p>');if(db.credits<=0){sub='Packages & Billing';render();return toast('No credits remaining. Upgrade or buy a top-up.')}db.credits--;db.unlocked.push(id);log('Preview candidate unlocked: '+id);render()}
function packages(admin=false){return pageHead(admin?'Configure employer packages':'A plan for every hiring journey',admin?'Prices are intentionally blank until supplied by the owner.':'Job seekers are always free. Employer package quotas follow the developer brief.')+'<div class="notice">Paid prices have not been provided. Payment gateways, invoices and server-confirmed credit grants are not connected. No payments are collected in this preview.</div><div class="plans">'+db.plans.map((p,i)=>'<div class="plan '+(i===2?'recommended':'')+'"><div class="eyebrow">'+p.name+'</div><h2>'+(p.price!==''?'PKR '+money(p.price):'Price on request')+'</h2><p>'+(p.validity?p.validity+' days validity':'Get started with the essentials')+'</p><ul><li>'+p.posts+' live job posts</li><li>'+p.days+' ad days per job</li><li>'+p.views+' profile unlocks</li><li>'+p.downloads+' CV downloads</li><li>'+p.featured+' featured job credits</li><li>'+p.team+' team members</li><li>'+(i===3?'API & webhooks':'Built-in applicant tracking')+'</li></ul><button class="btn '+(i===2?'':'light')+'" style="width:100%" onclick="'+(admin?'editPlan('+i+')':i===0?'toast(\'Free package is active in this preview.\')':'billingRequest(\''+p.name+'\')')+'">'+(admin?'Edit package':i===0?'Current plan':'Enquire about '+p.name)+'</button></div>').join('')+'</div>'+(!admin?'<div class="panel" style="margin-top:25px"><h3>Usage & billing</h3><p style="font-size:12px">Payment methods planned: JazzCash, Easypaisa, card and manually approved bank transfer. Credits are granted only after confirmed payment.</p><button class="btn light sm" onclick="billingRequest(\'CV credit top-up\')">Request credit top-up</button></div>':'')}
function billingRequest(p){modal('<h2>'+esc(p)+'</h2><p>Pricing and checkout are awaiting configuration by HRWala. No payment or package activation will occur in this preview.</p><button class="btn light" onclick="closeModal()">Understood</button>')}function editPlan(i){let p=db.plans[i];modal('<h2>Edit '+p.name+'</h2><form onsubmit="event.preventDefault();let d=Object.fromEntries(new FormData(this));for(let k in d)db.plans['+i+'][k]=d[k]===\'\'?\'\':Number(d[k]);log(\'Package updated\');closeModal();render()"><div class="fields">'+Object.entries({price:'Price (PKR)',validity:'Validity (days)',posts:'Live posts',days:'Ad days',views:'CV views',downloads:'CV downloads',featured:'Featured credits',team:'Team members'}).map(([k,l])=>field(l,k,p[k],'number')).join('')+'</div><div class="formactions"><button class="btn">Save package</button></div></form>')}
function audit(){return '<div class="panel"><h3>Activity history</h3><div class="notice">This is a local preview log. Production audit logs must be written by the server with authenticated actor and IP.</div>'+db.activity.slice(0,30).map(a=>'<div class="row"><div><b>'+esc(a.action)+'</b><small>'+esc(a.actor)+'</small></div><small>'+new Date(a.time).toLocaleString()+'</small></div>').join('')+'</div>'}
function team(){return pageHead('Better hiring, together','Manage your team and their responsibilities.')+'<div class="notice">Invites are saved locally in this preview; no email is sent. Free tier allows '+db.plans[0].team+' member.</div><div class="panel"><form onsubmit="event.preventDefault();if(db.team.length+1>=db.plans[0].team)return toast(\'Your team limit is reached. Upgrade your package.\');db.team.push(Object.fromEntries(new FormData(this)));log(\'Team invitation drafted\');render()"><div class="fields">'+field('Work email','email','','email',null,true)+field('Team role','role','Recruiter','text',['Owner','Hiring Manager','Recruiter','Viewer'])+'</div><div class="formactions"><button class="btn">Invite team member</button></div></form><div class="row"><b>You</b><span class="tag blue">Owner</span></div>'+db.team.map(t=>'<div class="row"><b>'+esc(t.email)+'</b><span class="tag">'+esc(t.role)+' · Invite draft</span></div>').join('')+'</div>'}
function simpleEditor(title,desc,fields,key){return pageHead(title,desc)+'<div class="panel"><form onsubmit="event.preventDefault();db[\''+key+'\']=Object.fromEntries(new FormData(this));log(\''+title+' updated\');toast(\'Settings saved on this browser.\')"><div class="fields">'+fields+'</div><div class="formactions"><button class="btn">Save changes</button></div></form></div>'}
function dashContent(){if(sub==='Overview')return overview();if(role==='seeker'){if(sub==='Profile')return profileForm();if(sub==='My CVs')return cvs();if(sub==='Documents')return documents();if(sub==='Applications')return pageHead('Every application. Every next step.','Your application history remains available in this browser.')+'<div class="panel">'+applicationRows()+'</div>';if(sub==='Saved Jobs & Alerts')return pageHead('Keep the right opportunities close','Saved roles and your job alert preferences.')+'<div class="panel"><h3>Job alerts</h3>'+(db.alerts.map(a=>'<div class="row"><b>'+esc(a.query||'All jobs')+'</b><span>'+esc(a.city||'All cities')+'</span></div>').join('')||'<p>No alerts yet. Create one from job search.</p>')+'</div><div class="jobs">'+db.jobs.filter(j=>db.saved.includes(j.id)).map(jobCard).join('')+'</div>';if(sub==='Portfolio')return portfolio();if(sub==='Notifications')return pageHead('Your updates','Application changes and saved activity.')+'<div class="panel">'+db.applications.flatMap(a=>a.history.map(h=>'<div class="row"><b>Application '+esc(h.status.toLowerCase())+'</b><small>'+new Date(h.date).toLocaleString()+'</small></div>')).join('')+'<p style="font-size:11px">Email and messaging services are awaiting configuration.</p></div>';if(sub==='Settings')return simpleEditor('Your privacy & preferences','Choose how employers discover your profile.',field('Profile visibility','visibility',db.profile.visibility,'text',['Public','Employers only','Hidden'])+field('Job alert frequency','frequency','Weekly','text',['Daily','Weekly','Off']),'preferences')+'<div class="panel"><h3>Account security</h3><p style="font-size:12px">Password changes and account deletion require a connected authentication service.</p></div>'}
if(role==='employer'){if(sub==='Company Profile')return companyForm();if(sub==='Post a Job')return postJob();if(sub==='My Jobs')return myJobs();if(sub==='Applicants (ATS)')return ats();if(sub==='Candidate Search')return candidateSearch();if(sub==='Unlocked CVs')return candidateSearch(true);if(sub==='Team')return team();if(sub==='Packages & Billing')return packages();if(sub==='Activity Log')return audit();if(sub==='Integrations')return pageHead('Connect your hiring workflow','Premium integrations for your ATS and career pages.')+'<div class="panel"><h3>REST API & signed webhooks</h3><div class="notice">Premium feature. API keys, scoped permissions and signed events require a production server. No keys are generated in this preview.</div><div class="row"><div><b>Application events</b><small>new_application · status_change</small></div><span class="tag">Not connected</span></div><div class="row"><div><b>Job feed import</b><small>XML / JSON · deduplicated by external job ID</small></div><span class="tag">Not connected</span></div><button class="btn light sm" onclick="sub=\'Packages & Billing\';render()">Explore Premium ↗</button></div>'}
if(role==='admin'){if(sub==='Job Approvals')return myJobs(true);if(sub==='Employer Approvals')return pageHead('Employer verification','Review the company before allowing publication.')+'<div class="panel"><h3>'+esc(db.company.name||'No company submitted')+'</h3><p>'+esc(db.company.about)+'</p><div class="row"><b>Status</b><span class="tag blue">'+esc(db.company.status)+'</span></div><div class="row"><b>Verification reference</b><span>'+esc(db.company.verification||'Not provided')+'</span></div><div class="formactions"><button class="btn light" onclick="rejectCompany()">Reject with reason</button><button class="btn" onclick="if(!db.company.name)return toast(\'No company to approve.\');db.company.status=\'Approved\';log(\'Company approved\');render()">Approve company</button></div></div>';if(sub==='Packages & Prices')return packages(true);if(sub==='Audit Log')return audit();if(sub==='Master Data')return simpleEditor('Master data','Edit the lists used throughout the portal.',Object.keys(db.masters).map(k=>field(k[0].toUpperCase()+k.slice(1)+' (comma separated)',k,db.masters[k],'textarea')).join(''),'masters');if(sub==='Payments & Credits')return pageHead('Payments & credit adjustments','Preview manual adjustments. No real payment is processed.')+'<div class="panel"><form onsubmit="event.preventDefault();db.credits=Math.max(0,db.credits+Number(this.views.value));db.downloadCredits=Math.max(0,db.downloadCredits+Number(this.downloads.value));log(\'Manual credit adjustment: \'+this.reason.value);render();toast(\'Preview credits adjusted.\')"><div class="fields">'+field('Profile unlock credits (+ / −)','views',0,'number')+field('Download credits (+ / −)','downloads',0,'number')+field('Reason for adjustment','reason','','textarea',null,true)+'</div><div class="formactions"><button class="btn">Apply preview adjustment</button></div></form></div>';if(sub==='Job Sources')return sources();if(sub==='Content')return simpleEditor('Content management','Prepare banners, policy pages and email copy.',field('Homepage banner','banner',db.content?.banner)+field('Terms of use','terms',db.content?.terms,'textarea')+field('Privacy policy','privacy',db.content?.privacy,'textarea')+field('Posting policy','posting',db.content?.posting,'textarea')+field('Application email template','emailTemplate',db.content?.emailTemplate,'textarea'),'content');if(sub==='Staff Roles')return simpleEditor('Staff roles','Draft staff permissions. Enforcement requires server authentication.',field('Staff email','email',db.staff?.email,'email')+field('Role','role',db.staff?.role,'text',['Moderator','Billing','Content Editor','Super Admin']),'staff');if(sub==='Users & Reports')return pageHead('Users & reports','Preview registered profile and report workflow.')+'<div class="panel"><div class="row"><div><b>'+esc(db.profile.name||'No seeker profile created')+'</b><small>'+esc(db.profile.email)+'</small></div><span class="tag">Job Seeker</span></div><div class="notice">Production user bans and abuse reports require authenticated server records.</div></div>'}return ''}
function rejectCompany(){modal('<h2>Reason for rejection</h2><form onsubmit="event.preventDefault();db.company.reason=this.reason.value;db.company.status=\'Rejected\';log(\'Company rejected\');closeModal();render()">'+field('Reason visible to employer','reason','','textarea',null,true)+'<div class="formactions"><button class="btn">Save decision</button></div></form>')}
function portfolio(){return pageHead('Show the work behind your skills','Add projects, context and links to your portfolio.')+'<div class="panel"><form onsubmit="event.preventDefault();db.portfolio.push(Object.fromEntries(new FormData(this)));log(\'Portfolio project saved\');render()"><div class="fields">'+field('Project title','title','','text',null,true)+field('Project URL','url','','url')+field('Project date','date','','date')+field('Description','description','','textarea')+'</div><div class="formactions"><button class="btn">Add project</button></div></form></div>'+db.portfolio.map(p=>'<div class="panel"><h3>'+esc(p.title)+'</h3><p>'+esc(p.description)+'</p>'+(p.url&&/^https?:\/\//.test(p.url)?'<a class="btn ghost sm" href="'+esc(p.url)+'" target="_blank" rel="noopener">View project ↗</a>':'')+'</div>').join('')}
function sources(){return pageHead('Career page sources','Maintain permitted job feed and career page sources.')+'<div class="notice">This registry saves configuration only. Scheduled fetching, robots.txt checks, extraction, deduplication and moderation require the production ingestion service.</div><div class="panel"><form onsubmit="event.preventDefault();db.sources.push(Object.fromEntries(new FormData(this)));log(\'Job source added\');render()"><div class="fields">'+field('Company','company','','text',null,true)+field('Career URL','url','','url',null,true)+field('Method','method','Employer feed / API','text',['Employer feed / API','Schema.org / RSS','Public ATS board','Custom HTML','Manual'])+field('Frequency','frequency','24 hours','text',['6 hours','12 hours','24 hours'])+field('Permission status','permission','Pending','text',['Pending','Written permission','Public feed','Not permitted'])+'</div><div class="formactions"><button class="btn">Save source</button></div></form></div>'+db.sources.map(s=>'<div class="panel"><b>'+esc(s.company)+'</b><p>'+esc(s.url)+' · '+esc(s.permission)+'</p></div>').join('')}
function policy(title){let k=title==='Terms of use'?'terms':title==='Privacy policy'?'privacy':'posting';modal('<h2>'+title+'</h2><p style="white-space:pre-line">'+esc(db.content?.[k]||'The owner-approved policy has not been supplied yet. This portal is an interactive preview; do not enter confidential information.')+'</p>')}
function auth(signup=false){return '<div class="auth panel"><div class="eyebrow">Welcome to HRWala</div><h1>'+(signup?'Start your next chapter.':'Good to see you again.')+'</h1><p style="font-size:12px">'+(signup?'Choose one account role. Job seeker access is always free.':'Explore your workspace in this interactive preview.')+'</p><div class="notice">Authentication, password security and verification emails are not connected. Do not enter a real password.</div><form onsubmit="event.preventDefault();role=this.role.value;if(role===\'seeker\'){db.profile.name=this.fullname?.value||db.profile.name;db.profile.email=this.email.value}else{db.company.email=this.email.value}persist();dash(role);toast(\'Preview workspace opened. No account was created.\')"><div class="fields">'+field('I am a','role','seeker','text',['seeker','employer'])+(signup?field('Full name / contact name','fullname','','text',null,true):'')+field('Email','email','','email',null,true)+'</div><div class="formactions"><button class="btn" style="width:100%">Open preview workspace ↗</button></div></form><p style="text-align:center;font-size:11px"><a href="#" onclick="go(\''+(signup?'signin':'signup')+'\');return false">'+(signup?'Already have an account? Sign in':'New here? Create an account')+'</a></p></div>'}
function companies(){return '<div class="container">'+pageHead('Find a team you can grow with','Explore the companies behind the opportunities.')+'<div class="jobs">'+[...new Set(db.jobs.map(j=>j.company))].map(c=>'<div class="job"><div class="companylogo">'+esc(c.slice(0,2))+'</div><h3>'+esc(c)+'</h3><p style="font-size:11px">Illustrative employer · Pakistan</p><button class="btn light sm" onclick="query=\''+esc(c)+'\';go(\'jobs\')">View opportunities ↗</button></div>').join('')+'</div></div>'}
function resources(){return '<div class="container">'+pageHead('Make your next move with confidence','Practical tools for your professional journey.')+'<div class="jobs">'+[['01','Build a clear, focused CV','Start with your experience, show the outcomes of your work and tailor your skills to the role.','Open CV builder','My CVs'],['02','Tell your professional story','A complete profile helps a hiring team understand the strengths you bring.','Complete your profile','Profile'],['03','Stay on top of every application','Track your application timeline and keep your next steps organised in one place.','Track applications','Applications']].map(([n,t,p,b,s])=>'<div class="job"><div class="eyebrow">Career guide '+n+'</div><h3>'+t+'</h3><p style="font-size:12px">'+p+'</p><button class="btn light sm" onclick="dash(\'seeker\');sub=\''+s+'\';render()">'+b+' ↗</button></div>').join('')+'</div></div>'}
function render(){$('#app').innerHTML=header()+(page==='home'?home():page==='jobs'?jobsPage():page==='dashboard'?workspace():page==='companies'?companies():page==='resources'?resources():auth(page==='signup'))+footer()}
window.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});render();
